 using Microsoft.VisualStudio.TestTools.UnitTesting;

 namespace Contoso.Pricing.Tests;

 [TestClass]
 public sealed class PriceCalculatorTests
 {
     private PriceCalculator _calculator = null!;

     [TestInitialize]
     public void Setup() => _calculator = new PriceCalculator();

     // --- CalculateTotal: DataRow for inline cases ---

     [TestMethod]
     [DataRow(10.00, 1, 0.0, 10.00, DisplayName = "Single item, no tax")]
     [DataRow(10.00, 5, 0.0, 50.00, DisplayName = "Multiple items, no tax")]
     [DataRow(10.00, 1, 0.10, 11.00, DisplayName = "Single item, 10% tax")]
     [DataRow(25.50, 3, 0.08, 82.62, DisplayName = "Fractional price, 8% tax")]
     [DataRow(0.00, 10, 0.15, 0.00, DisplayName = "Zero price")]
     [DataRow(99.99, 0, 0.20, 0.00, DisplayName = "Zero quantity")]
     public void CalculateTotal_ValidInputs_ReturnsExpected(
         double unitPrice, int quantity, double taxRate, double expected)
     {
         var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

         Assert.AreEqual((decimal)expected, result);
     }

     // --- CalculateTotal: DynamicData for complex/edge cases ---

     public static IEnumerable<object[]> CalculateTotalEdgeCases
     {
         get
         {
             yield return new object[] { 0.01m, 1, 0m, 0.01m, "Minimum meaningful price" };
             yield return new object[] { 9999.99m, 100, 1m, 1_999_998.00m, "Large order, max tax" };
             yield return new object[] { 5.00m, 1, 0.0725m, 5.3625m, "Precise tax rate (7.25%)" };
         }
     }

     [TestMethod]
     [DynamicData(nameof(CalculateTotalEdgeCases))]
     public void CalculateTotal_EdgeCases_ReturnsExpected(
         decimal unitPrice, int quantity, decimal taxRate, decimal expected, string scenario)
     {
         var result = _calculator.CalculateTotal(unitPrice, quantity, taxRate);

         Assert.AreEqual(expected, result, $"Failed for scenario: {scenario}");
     }

     // --- CalculateTotal: invalid inputs ---

     [TestMethod]
     [DataRow(-1.00, 1, 0.10, DisplayName = "Negative unit price")]
     public void CalculateTotal_NegativePrice_Throws(double unitPrice, int quantity, double taxRate)
     {
         Assert.ThrowsException<ArgumentOutOfRangeException>(
             () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));
     }

     [TestMethod]
     [DataRow(10.00, -1, 0.10, DisplayName = "Negative quantity")]
     public void CalculateTotal_NegativeQuantity_Throws(double unitPrice, int quantity, double taxRate)
     {
         Assert.ThrowsException<ArgumentOutOfRangeException>(
             () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));
     }

     [TestMethod]
     [DataRow(10.00, 1, -0.01, DisplayName = "Tax rate below 0")]
     [DataRow(10.00, 1, 1.01, DisplayName = "Tax rate above 1")]
     public void CalculateTotal_InvalidTaxRate_Throws(double unitPrice, int quantity, double taxRate)
     {
         Assert.ThrowsException<ArgumentOutOfRangeException>(
             () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));
     }

     // --- ApplyDiscount: DataRow ---

     [TestMethod]
     [DataRow(100.00, 0.0, 100.00, DisplayName = "No discount")]
     [DataRow(100.00, 10.0, 90.00, DisplayName = "10% off")]
     [DataRow(100.00, 50.0, 50.00, DisplayName = "50% off")]
     [DataRow(100.00, 100.0, 0.00, DisplayName = "100% off (free)")]
     [DataRow(49.99, 25.0, 37.4925, DisplayName = "Fractional result")]
     public void ApplyDiscount_ValidInputs_ReturnsExpected(
         double price, double discountPercent, double expected)
     {
         var result = _calculator.ApplyDiscount((decimal)price, (decimal)discountPercent);

         Assert.AreEqual((decimal)expected, result);
     }

     // --- ApplyDiscount: DynamicData from method ---

     public static IEnumerable<object[]> InvalidDiscountCases()
     {
         yield return new object[] { 100m, -1m, "Negative discount" };
         yield return new object[] { 100m, 100.01m, "Discount exceeds 100%" };
         yield return new object[] { 50m, 200m, "Wildly over 100%" };
     }

     [TestMethod]
     [DynamicData(nameof(InvalidDiscountCases), DynamicDataSourceType.Method)]
     public void ApplyDiscount_InvalidDiscount_Throws(
         decimal price, decimal discountPercent, string scenario)
     {
         Assert.ThrowsException<ArgumentOutOfRangeException>(
             () => _calculator.ApplyDiscount(price, discountPercent),
             $"Expected exception for: {scenario}");
     }
 }
